head.script:
scwin.FMT = "yyyy년 MM월 dd일 (E) HH:mm:ss";
scwin.DAYS = ["일", "월", "화", "수", "목", "금", "토"];

scwin.onpageload = function() {
	// 2021-07-12(월) KST 기준: 오전 9시 전·후(UTC 날짜가 바뀌는 경계) + 당일 0시·23시59분59초
	var times = [1626047977000, 1626048077000, new Date(2021, 6, 12, 0, 0, 0).getTime(), new Date(2021, 6, 12, 23, 59, 59).getTime()];
	window.result = times.map(function(ts) {
		var d = new Date(ts);
		var p2 = function(n) { return (n < 10 ? "0" : "") + n; };
		var exp = d.getFullYear() + "년 " + p2(d.getMonth() + 1) + "월 " + p2(d.getDate()) + "일 (" + scwin.DAYS[d.getDay()] + ") "
			+ p2(d.getHours()) + ":" + p2(d.getMinutes()) + ":" + p2(d.getSeconds());
		return { got: $p.getFormattedDate(d, scwin.FMT), exp: exp };
	});
};

scwin.getResult = function() {
	return window.result;
};
